import numpy as np
import pandas as pd

def task_func(country_dict):
    if country_dict is None:
        return pd.DataFrame(columns=["GDP"])

    try:
        countries = list(country_dict.keys())
    except AttributeError:
        countries = list(country_dict)

    if not countries:
        return pd.DataFrame(columns=["GDP"])

    gdp_values = np.random.randint(
        1_000_000_000,
        100_000_000_001,
        size=len(countries),
    )

    return pd.DataFrame({"GDP": gdp_values}, index=countries)
